with deduped as (select *, row_number() over (partition by customer_id order by started_at desc nulls last, id) as row_num from sessions qualify row_num = 1) select browser, country, count(*) filter (where browser = 'Edge') as edge_rows, sort_array(collect_set(device)) as device_list, count_if(browser = 'Edge') as edge_events, size(collect_set(country)) as num_countries, max(started_at) as ended_at, grouping_id() as grouping_id from deduped group by grouping sets ((browser, country), (browser)) order by edge_events nulls last
